 3	public final class BinarySearch {
 4	    public static final int NOT_FOUND = -1;
 5	
 6	    private BinarySearch() {
 7	    }
 8	
 9	    public static int binarySearch(int[] sortedValues, int target) {
10	        Objects.requireNonNull(sortedValues, "sortedValues");
11	
12	        int low = 0;
13	        int high = sortedValues.length - 1;
14	
15	        while (low <= high) {
16	            int mid = low + (high - low) / 2;
17	            int value = sortedValues[mid];
18	
19	            if (value == target) {
20	                return mid;
21	            }
22	
23	            if (value < target) {
24	                low = mid + 1;
25	            } else {
26	                high = mid - 1;
27	            }
28	        }
29	
30	        return NOT_FOUND;
31	    }
32	}
